def choose_move(observation):
    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    env = observation.get("environment_name", "")
    self_pos = pos(observation.get("self_position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position")) or self_pos
    sx, sy = self_pos
    ox, oy = opp_pos

    gw = observation.get("grid_width")
    gh = observation.get("grid_height")
    if not isinstance(gw, int) or gw <= 0:
        gw = 0
    if not isinstance(gh, int) or gh <= 0:
        gh = 0

    role = observation.get("self_role", "")

    if env == "pursuit_evasion":
        if role == "pursuer":
            return clamp_move(sign(ox - sx), sign(oy - sy))
        corners = []
        if gw and gh:
