            return clamp_move(sign(target[0] - sx), sign(target[1] - sy))
        return clamp_move(-sign(ox - sx), -sign(oy - sy))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_d = None
        for item in targets:
            p = pos(item)
            if p is None:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best_d is None or d < best_d:
                best_d = d
                best = p
        if best is not None:
            return clamp_move(sign(best[0] - sx), sign(best[1] - sy))
        return clamp_move(sign(ox - sx), sign(oy - sy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_d = None
    for item in resources:
        p = pos(item)
        if p is None:
            continue
        d = abs(p[0] - sx) + abs(p[1] - sy)
        if best_d is None or d < best_d:
            best_d = d
            best = p
    if best is not None:
        return clamp_move(sign(best[0] - sx), sign(best[1] - sy))

    return clamp_move(sign(ox - sx), sign(oy - sy))

